package com.example.examplemod;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;

/**
 * Read-only collision markup for ANY decoded Chameleon model.
 *
 * Unlike the old reference hair-geo probe, this walks every bone/cube, reads
 * the actual quad positions generated by the Chameleon model parser, and
 * preserves each cube's own pivot and rotation. No cube is measured from
 * guessed Blockbench X signs. The caller supplies the SAME cleaned rendered
 * world-space bone source used for Jolt hair.
 *
 * A simulated hair bone is not also a passive body collider: those names are
 * excluded by the caller, following Wemppy's distinct collision/chain owners.
 */
public final class BodyPartChameleonCollisionBoxes
{
    private BodyPartChameleonCollisionBoxes() {}
    public static final int MAX_BOXES=32;

    public static List<float[]> collect(Object chameleonMorph,
            BodyPartPhysicsWorldPose.MatrixSource world,
            Set<String> simulatedBones)
    {
        if(chameleonMorph==null || world==null ||
                !chameleonMorph.getClass().getName().endsWith(".ChameleonMorph"))
            return Collections.emptyList();
        try
        {
            Object wrapper=chameleonMorph.getClass().getMethod("getModel").invoke(chameleonMorph);
            Object model=field(wrapper,"model");
            Object roots=field(model,"bones");
            if(!(roots instanceof List))return Collections.emptyList();
            List<float[]> result=new ArrayList<float[]>();
            walk((List<?>)roots,world,simulatedBones,result,
                    new IdentityHashMap<Object,Boolean>());
            return result;
        }
        catch(ReflectiveOperationException error)
        {
            return Collections.emptyList();
        }
    }

    private static void walk(List<?> bones,
            BodyPartPhysicsWorldPose.MatrixSource world,
            Set<String> simulated, List<float[]> result,
            IdentityHashMap<Object,Boolean> visited)
            throws ReflectiveOperationException
    {
        for(Object bone:bones)
        {
            if(bone==null || visited.put(bone,Boolean.TRUE)!=null)continue;
            String id=String.valueOf(field(bone,"id"));
            if(simulated==null || !simulated.contains(id))
            {
                float[] matrix=world.getBoneWorldMatrix(id);
                Object initial=field(bone,"initial");
                if(matrix!=null && initial!=null)
                {
                    float[] bonePivot=xyz(field(initial,"translate"));
                    Object raw=field(bone,"cubes");
                    if(raw instanceof List)
                        for(Object cube:(List<?>)raw)
                        {
                            if(result.size()>=MAX_BOXES)return;
                            if(cube==null)continue;
                            try
                            {
                                float[] fitted=fitOne(cube,matrix,bonePivot);
                                if(fitted!=null)result.add(fitted);
                            }
                            catch(IllegalArgumentException ignored)
                            {
                                // Invalid, sheared or degenerate primitives
                                // must not add false physical contacts.
                            }
                        }
                }
            }
            Object children=field(bone,"children");
            if(children instanceof List)
                walk((List<?>)children,world,simulated,result,visited);
            if(result.size()>=MAX_BOXES)return;
        }
    }

    private static float[] fitOne(Object cube,float[] matrix,float[] bonePivot)
            throws ReflectiveOperationException
    {
        Object faces=field(cube,"quads");
        if(!(faces instanceof List))return null;
        List<float[]> points=new ArrayList<float[]>();
        for(Object face:(List<?>)faces)
        {
            Object vertices=field(face,"vertices");
            if(!(vertices instanceof List))continue;
            for(Object vertex:(List<?>)vertices)
                points.add(xyz(field(vertex,"position")));
        }
        if(points.size()<4)return null;
        return BodyPartJoltBoxGeometry.fit(matrix,bonePivot,
                xyz(field(cube,"pivot")),xyz(field(cube,"rotation")),
                points.toArray(new float[points.size()][]));
    }

    private static Object field(Object obj,String name)
            throws ReflectiveOperationException
    {
        if(obj==null)throw new NoSuchFieldException(name+" on null");
        Field field=obj.getClass().getField(name);
        return field.get(obj);
    }

    private static float[] xyz(Object vector)
            throws ReflectiveOperationException
    {
        return new float[] {
                ((Number)field(vector,"x")).floatValue(),
                ((Number)field(vector,"y")).floatValue(),
                ((Number)field(vector,"z")).floatValue()
        };
    }
}
